1	import type { Db } from "@paperclipai/db";
2	import type { StorageService } from "../storage/types.js";
3	
4	/** Normalized actor from auth middleware — only set when authenticated (not "none"). */
5	export interface ActorContext {
6	  type: "board" | "agent";
7	  userId?: string;
8	  agentId?: string;
9	  companyId?: string;
10	}
11	
12	/** Minimal normalized request passed to every handler. */
13	export interface RequestCtx {
14	  method: string;
15	  url: URL;
16	  headers: Headers;
17	  json<T = unknown>(): Promise<T>;
18	  text(): Promise<string>;
19	  /** Path param: e.g. ctx.param("companyId") */
20	  param(name: string): string | undefined;
21	  /** Query param */
22	  query(name: string): string | undefined;
23	  actor: ActorContext | null;
24	  db: Db;
25	  storage: StorageService;
26	}
27	
28	export type Handler = (ctx: RequestCtx) => Promise<Response>;
29	
30	export interface RouteDefinition {
31	  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
32	  /** Express-style path, e.g. /api/companies/:companyId */
33	  path: string;
34	  handler: Handler;
35	}
